  goals:[["calm","Una noche normal pasa, con un aviso"],["held","Una noche mala se detiene, y el dueño lo arregla"],["census","La cifra de Planificación nunca sale mal"]],
  ownT:"Cada control nombra su dueño y dimensión",lvL:"Sin correo: el nivel del equipo de aprendizaje",lvs:[["any","Detener con uno"],["five","Avisar, detener sobre cinco"],["never","No detener nunca"]],
  plL:"Cuadre con el censo: el nivel de Planificación",pls:[["stop","Detener con cualquier diferencia"],["warn","Solo avisar"]],
  n2B:"Noche normal: 2 sin correo",n6B:"Noche mala: 6",diffB:"La cifra difiere en 3",
